import time

from ._sdk import BrainAgent, BrainConfig

log = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "capture_intent",
        "description": (
